<template><div class="page"><h2>故障树编辑</h2><el-button type="primary" @click="add">新增节点</el-button><el-button @click="save">保存</el-button><el-table :data="nodes" style="margin-top:16px"><el-table-column label="名称"><template #default="s"><el-input v-model="s.row.name"/></template></el-table-column><el-table-column label="类型"><template #default="s"><el-select v-model="s.row.type"><el-option label="事件" value="event"/><el-option label="AND" value="AND"/><el-option label="OR" value="OR"/></el-select></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="nodes.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';const nodes=ref([]);async function load(){const r=await fetch('/api/v1/knowledge/fault-trees/');const d=await r.json();nodes.value=d[0]?.graph?.nodes||[]}function add(){nodes.value.push({id:Date.now(),name:'新节点',type:'event'})}async function save(){const r=await fetch('/api/v1/knowledge/fault-trees/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'默认故障树',graph:{nodes:nodes.value,edges:[]}})});if(r.ok)ElMessage.success('故障树已保存')}onMounted(load)</script><style scoped>.page{max-width:1100px}.el-button{margin-right:8px}</style>
